'use strict';

// MODULES //

var dswap = require( '@stdlib/blas/base/dswap' ).ndarray;


// FUNCTIONS //

/**
* Swaps stored row fragments in their existing sequential order.
* @private
* @param {Float64Array} A - matrix
* @param {integer} s1 - row stride
* @param {integer} s2 - column stride
* @param {integer} oa - matrix offset
* @param {integer} row - first row
* @param {integer} target - second row
* @param {NonNegativeInteger} start - first column
* @param {NonNegativeInteger} count - fragment length
* @returns {void}
*/
function swap( A, s1, s2, oa, row, target, start, count ) { // eslint-disable-line max-params
	if ( count > 0 && row !== target ) {
		dswap( count, A, s2, oa+(row*s1)+(start*s2), A, s2, oa+(target*s1)+(start*s2) );
	}
}


// MAIN //

/**
* Converts or reverts validated symmetric indefinite rook factor storage.
*
* Adapted from Reference-LAPACK DSYCONVF_ROOK at commit 2e5d9c1273435fbd953adb294ed603e4789afaba. See NOTICE for retained BSD copyright, conditions and disclaimer.
*
* @private
* @param {integer} u - triangle enum
* @param {integer} w - C/R direction enum
* @param {PositiveInteger} N - matrix order
* @param {Float64Array} A - factor matrix
* @param {integer} s1 - row stride
* @param {integer} s2 - column stride
* @param {integer} oa - matrix offset
* @param {Float64Array} E - off-diagonal storage
* @param {integer} se - storage stride
* @param {integer} oe - storage offset
* @param {Int32Array} P - signed one-based pivots
* @param {integer} sp - pivot stride
* @param {integer} op - pivot offset
* @returns {integer} zero success status
*/
function base( u, w, N, A, s1, s2, oa, E, se, oe, P, sp, op ) { // eslint-disable-line max-params
	var p;
	var q;
	var i;
	if ( w === 67 ) {
		if ( u === 121 ) {
			i = N-1;
			E[ oe ] = 0.0;
			while ( i > 0 ) {
				if ( P[ op+(i*sp) ] < 0 ) {
					E[ oe+(i*se) ] = A[ oa+((i-1)*s1)+(i*s2) ];
					E[ oe+((i-1)*se) ] = 0.0;
					A[ oa+((i-1)*s1)+(i*s2) ] = 0.0;
					i -= 1;
				} else {
					E[ oe+(i*se) ] = 0.0;
				}
				i -= 1;
			}
			i = N-1;
			while ( i >= 0 ) {
				p = P[ op+(i*sp) ];
				if ( p > 0 ) {
					swap( A, s1, s2, oa, i, p-1, i+1, N-i-1 );
				} else {
					q = P[ op+((i-1)*sp) ];
					swap( A, s1, s2, oa, i, -p-1, i+1, N-i-1 );
					swap( A, s1, s2, oa, i-1, -q-1, i+1, N-i-1 );
					i -= 1;
				}
				i -= 1;
			}
		} else {
			i = 0;
			E[ oe+((N-1)*se) ] = 0.0;
			while ( i < N ) {
				if ( i < N-1 && P[ op+(i*sp) ] < 0 ) {
					E[ oe+(i*se) ] = A[ oa+((i+1)*s1)+(i*s2) ];
					E[ oe+((i+1)*se) ] = 0.0;
					A[ oa+((i+1)*s1)+(i*s2) ] = 0.0;
					i += 1;
				} else {
					E[ oe+(i*se) ] = 0.0;
				}
				i += 1;
			}
			i = 0;
			while ( i < N ) {
				p = P[ op+(i*sp) ];
				if ( p > 0 ) {
					swap( A, s1, s2, oa, i, p-1, 0, i );
				} else {
					q = P[ op+((i+1)*sp) ];
					swap( A, s1, s2, oa, i, -p-1, 0, i );
					swap( A, s1, s2, oa, i+1, -q-1, 0, i );
					i += 1;
				}
				i += 1;
			}
		}
	} else if ( u === 121 ) {
		i = 0;
		while ( i < N ) {
			p = P[ op+(i*sp) ];
			if ( p > 0 ) {
				swap( A, s1, s2, oa, i, p-1, i+1, N-i-1 );
			} else {
				i += 1;
				p = P[ op+(i*sp) ];
				q = P[ op+((i-1)*sp) ];
				swap( A, s1, s2, oa, i-1, -q-1, i+1, N-i-1 );
				swap( A, s1, s2, oa, i, -p-1, i+1, N-i-1 );
			}
			i += 1;
		}
		i = N-1;
		while ( i > 0 ) {
			if ( P[ op+(i*sp) ] < 0 ) {
				A[ oa+((i-1)*s1)+(i*s2) ] = E[ oe+(i*se) ];
				i -= 1;
			}
			i -= 1;
		}
	} else {
		i = N-1;
		while ( i >= 0 ) {
			p = P[ op+(i*sp) ];
			if ( p > 0 ) {
				swap( A, s1, s2, oa, i, p-1, 0, i );
			} else {
				i -= 1;
				p = P[ op+(i*sp) ];
				q = P[ op+((i+1)*sp) ];
				swap( A, s1, s2, oa, i+1, -q-1, 0, i );
				swap( A, s1, s2, oa, i, -p-1, 0, i );
			}
			i -= 1;
		}
		i = 0;
		while ( i < N-1 ) {
			if ( P[ op+(i*sp) ] < 0 ) {
				A[ oa+((i+1)*s1)+(i*s2) ] = E[ oe+(i*se) ];
				i += 1;
			}
			i += 1;
		}
	}
	return 0;
}

module.exports = base;
